function archiveDates({timestamp}) {
  const current=new Date(timestamp);
  if(!Number.isFinite(current.getTime()))throw new Error('Invalid schedule timestamp.');
  const month=current.getUTCMonth(),day=current.getUTCDate(),dates=[];
  for(let year=current.getUTCFullYear();year>=2007;year--){
    const date=new Date(Date.UTC(year,month,day));
    if(date.getUTCMonth()!==month||date.getUTCDate()!==day)continue;
    const value=date.toISOString().slice(0,10);
    if(value<'2007-02-19')continue;
    dates.push(value);
  }
  return {dates,count:dates.length};
}

return archiveDates({timestamp:$input.first().json.timestamp}).dates.map(date=>({json:{date},pairedItem:{item:0}}));

function decodeText(value) {
  const named={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi,(entity,key)=>{
    if(key[0]!=='#')return named[key.toLowerCase()]??entity;
    const number=key[1].toLowerCase()==='x'?parseInt(key.slice(2),16):Number(key.slice(1));
    return number>0&&number<=0x10ffff&&!(number>=0xd800&&number<=0xdfff)?String.fromCodePoint(number):entity;
  });
}

function extractArchives({pages}) {
  const archives=pages.map(({date,html})=>{
    if(typeof html!=='string'||!/<html\b/i.test(html)||!/Hacker News/i.test(html))throw new Error('The archive response is not a Hacker News page.');
    const headlines=[];
    const pattern=/<span\b[^>]*class=["'][^"']*\btitleline\b[^"']*["'][^>]*>\s*<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
    for(const match of html.matchAll(pattern)){
      const href=match[1].match(/\bhref\s*=\s*(?:"([^"]*)"|'([^']*)')/i);
      if(!href)throw new Error('A Hacker News title is missing its URL.');
      const url=new URL(decodeText(href[1]??href[2]),'https://news.ycombinator.com/');
      if(!['http:','https:'].includes(url.protocol))throw new Error('Unexpected headline URL scheme.');
      const title=decodeText(match[2].replace(/<[^>]*>/g,'')).replace(/\s+/g,' ').trim();
      if(!title)throw new Error('Empty Hacker News title.');
      headlines.push(title+' ['+url.href+']');
    }
    return {date,headlines};
  });
  return {archives,data:JSON.stringify(archives)};
}

const pages=$input.all().map((item,index)=>{if(item.json.statusCode<200||item.json.statusCode>=300)throw new Error('Hacker News archive request failed');return {date:$('CreateYearsList').itemMatching(index).json.date,html:item.json.body};});
return [{json:extractArchives({pages})}];

function validateSummary({text}) {
  if(typeof text!=='string'||!text.trim())throw new Error('The model did not return a summary.');
  if(text.length>4096)throw new Error('The summary exceeds the Telegram message limit of 4096 characters.');
  return {text};
}

return [{json:validateSummary({text:$input.first().json.text})}];
